class NormalDepthState(RobotControlState):
    def on_bind(self, ctx):
        self.pipeline = rs.pipeline()
        config = rs.config()
        config.enable_stream(rs.stream.depth, 640, 360, rs.format.z16, 30)
        self.pipeline.start(config)
        profile = self.pipeline.get_active_profile()
        depth_sensor = profile.get_device().first_depth_sensor()
        depth_sensor.set_option(rs.option.enable_auto_exposure, 1.0)
        self.depth_scale = depth_sensor.get_depth_scale()

        
    def debug_display(self,img, title="Image",scale = 1,video=None):
        print(f"{title} - shape: {img.shape}, dtype: {img.dtype}, range: [{img.min()}, {img.max()}]")
        height, width = img.shape[:2]
        new_size = (width * scale, height * scale)
        img = cv2.resize(img, new_size, interpolation=cv2.INTER_LINEAR)
        img_normalized = (img - img.min()) / (img.max() - img.min()) * 255
        img_uint8 = img_normalized.astype(np.uint8)
        # cv2.imshow(title, img_uint8)
        cv2.imwrite("/home/kkkk/depth.jpg",img_uint8)
        # cv2.waitKey(1)
    def apply_depth_filters(self,depth_frame):
        """对深度帧应用后处理滤波"""
        
        # 1. 初始化滤波器
        decimation = rs.decimation_filter()
        spatial = rs.spatial_filter()
        temporal = rs.temporal_filter()
        hole_filling = rs.hole_filling_filter()
        
        # 2. 优化参数配置（针对空洞填充）
        
        # 降采样：降低分辨率可以提高信噪比
        decimation.set_option(rs.option.filter_magnitude, 1)  # 改为1，保持分辨率
        
        # 空间滤波：关键参数调整
        spatial.set_option(rs.option.filter_smooth_alpha, 0.8)      # 提高平滑度
        spatial.set_option(rs.option.filter_smooth_delta, 10)       # 降低阈值，填充更多空洞
        spatial.set_option(rs.option.holes_fill, 3)                 # 3=启用高级空洞填充
        
        # 时域滤波：利用历史帧填充空洞
        temporal.set_option(rs.option.filter_smooth_alpha, 0.6)     # 提高历史帧权重
        temporal.set_option(rs.option.filter_smooth_delta, 10)      # 降低阈值
        
        # 空洞填充：关键参数
        # 0=禁用, 1=最近邻填充, 2=最远邻填充（适合大面积空洞）
        hole_filling.set_option(rs.option.holes_fill, 2)            # 使用最远邻填充
        
        # 3. 按顺序处理
        filtered_frame = decimation.process(depth_frame)
        filtered_frame = spatial.process(filtered_frame)
        filtered_frame = temporal.process(filtered_frame)
        filtered_frame = hole_filling.process(filtered_frame)
        
        return filtered_frame
    def learnable_downsample(self,depth_meters, target_size=(64, 36)):
        """
        使用双三次插值 + 细节增强
        """
        # 双三次插值（保留边缘）
        depth_bicubic = cv2.resize(depth_meters, target_size, interpolation=cv2.INTER_CUBIC)
        
        # 计算梯度信息
        sobelx = cv2.Sobel(depth_meters, cv2.CV_64F, 1, 0, ksize=3)
        sobely = cv2.Sobel(depth_meters, cv2.CV_64F, 0, 1, ksize=3)
        gradient = np.sqrt(sobelx**2 + sobely**2)
        
        # 梯度也降采样
        gradient_small = cv2.resize(gradient, target_size, interpolation=cv2.INTER_CUBIC)
        
        # 根据梯度增强细节
        result = depth_bicubic + gradient_small * 0.1
        
        return np.clip(result, 0, None)
    
    def on_prepare_enter(
        self,
        ctx: BxiExample,
        from_state: StateBehavior[BxiExample],
        transition: TransitionProfile,
    ) -> None:
        super().on_prepare_enter(ctx, from_state, transition)
        ctx.preheat_model(
            ctx.normal_depth,
            with_cmd_vel=True,
            cmd_vel=self.get_cmd_vel(ctx),
        )

    def get_first_frame(self, ctx: BxiExample) -> Optional[MotorFrame]:
        return self._motor_frame(
            ctx.normal_depth.target_dof_pos, ctx.normal_depth.kps, ctx.normal_depth.kds
        )

